/**
 * frontend/src/components/Enrollment.jsx - ENRÔLEMENT ÉTUDIANT
 * ✅ Version Design Premium
 */

import React, { useState } from 'react';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#2563EB',      // Bleu moderne
  primaryLight: '#EFF6FF',
  success: '#10B981',      // Vert clair
  successLight: '#D1FAE5',
  danger: '#EF4444',       // Rouge doux
  dangerLight: '#FEE2E2',
  textMain: '#1E2937',
  textMuted: '#64748B',
  border: '#E2E8F0',
  surface: '#FFFFFF',
  background: '#F8FAFC'
};

const Enrollment = ({ addNotification }) => {
  const [formData, setFormData] = useState({ name: '', email: '', level: '', filiere: '' });
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);
  const [messageType, setMessageType] = useState('info');

  const showMessage = (msg, type = 'info') => {
    setMessage(String(msg));
    setMessageType(type);

    if (type === 'success' || type === 'error') {
      setTimeout(() => setMessage(null), 5000);
    }
  };

  const handleFileSelect = (e) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    if (!selectedFile.type.startsWith("image/")) {
      showMessage("Veuillez sélectionner une image valide", "error");
      return;
    }

    setFile(selectedFile);

    const reader = new FileReader();
    reader.onload = (event) => {
      if (typeof event.target?.result === 'string') {
        setPreview(event.target.result);
      }
    };
    reader.readAsDataURL(selectedFile);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const name = formData.name.trim();
    const email = formData.email?.trim() || null;
    const level = formData.level;
    const filiere = formData.filiere;

    if (!name || !file || !level || !filiere) {
      showMessage("Nom, image, niveau et filière sont requis", "error");
      return;
    }

    setLoading(true);

    try {
      showMessage("Envoi en cours...", "info");

      const response = await studentsAPI.enrollFromImage(
        name,
        email,
        file,
        level,
        filiere
      );

      if (response.success) {
        showMessage(`${response.data.name} a été enrôlé avec succès`, "success");
        addNotification(`${response.data.name} enrôlé`, 'success');

        setFormData({ name: '', email: '', level: '', filiere: '' });
        setFile(null);
        setPreview(null);
      } else {
        throw new Error(response.error || "Erreur inconnue");
      }

    } catch (err) {
      const errorMsg = err.message || "Erreur serveur";
      showMessage(`Erreur : ${errorMsg}`, "error");
      addNotification(`Erreur : ${errorMsg}`, 'error');
    }

    setLoading(false);
  };

  const messageColors = {
    success: { bg: COLORS.successLight, text: '#166534' },
    error: { bg: COLORS.dangerLight, text: COLORS.danger },
    info: { bg: COLORS.primaryLight, text: COLORS.primary }
  };

  const msgColor = messageColors[messageType];

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>Enrôlement d'un étudiant</h2>

        {message && (
          <div style={{
            ...styles.message,
            backgroundColor: msgColor.bg,
            color: msgColor.text
          }}>
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit} style={styles.form}>
          <input
            type="text"
            placeholder="Nom complet"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            style={styles.input}
            disabled={loading}
            required
          />

          <input
            type="email"
            placeholder="Email (optionnel)"
            value={formData.email}
            onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            style={styles.input}
            disabled={loading}
          />

          <select
            value={formData.level}
            onChange={(e) => setFormData({ ...formData, level: e.target.value })}
            style={styles.input}
            disabled={loading}
            required
          >
            <option value="">Sélectionner le niveau</option>
            <option value="L1">L1</option>
            <option value="L2">L2</option>
            <option value="L3">L3</option>
            <option value="M1">M1</option>
            <option value="M2">M2</option>
            <option value="D1">D1</option>
            <option value="D2">D2</option>
          </select>

          <input
            type="text"
            placeholder="Filière"
            value={formData.filiere}
            onChange={(e) => setFormData({ ...formData, filiere: e.target.value })}
            style={styles.input}
            disabled={loading}
            required
          />

          <div style={styles.fileContainer}>
            <input
              type="file"
              accept="image/*"
              onChange={handleFileSelect}
              disabled={loading}
              required
              style={styles.fileInput}
            />
          </div>

          {preview && (
            <div style={styles.previewContainer}>
              <img
                src={preview}
                alt="Aperçu"
                style={styles.preview}
              />
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              ...styles.button,
              opacity: loading ? 0.75 : 1,
              cursor: loading ? 'not-allowed' : 'pointer'
            }}
          >
            {loading ? "Traitement en cours..." : "Enrôler l'étudiant"}
          </button>
        </form>
      </div>
    </div>
  );
};

const styles = {
  container: {
    maxWidth: "520px",
    margin: "40px auto",
    padding: "20px"
  },
  card: {
    backgroundColor: COLORS.surface,
    borderRadius: "20px",
    padding: "40px 35px",
    boxShadow: "0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)",
    border: `1px solid ${COLORS.border}`
  },
  title: {
    textAlign: "center",
    fontSize: "28px",
    fontWeight: "700",
    color: COLORS.textMain,
    marginBottom: "32px",
    letterSpacing: "-0.5px"
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "18px"
  },
  input: {
    padding: "14px 16px",
    borderRadius: "12px",
    border: `1px solid ${COLORS.border}`,
    fontSize: "15px",
    outline: "none",
    transition: "all 0.3s ease",
    backgroundColor: "#FAFBFC"
  },
  inputFocus: {
    borderColor: COLORS.primary,
    boxShadow: "0 0 0 3px rgba(37, 99, 235, 0.1)"
  },
  fileContainer: {
    padding: "8px 0"
  },
  fileInput: {
    width: "100%",
    padding: "12px",
    borderRadius: "12px",
    border: `2px dashed ${COLORS.border}`,
    backgroundColor: "#FAFBFC",
    cursor: "pointer",
    fontSize: "14px"
  },
  previewContainer: {
    marginTop: "8px",
    borderRadius: "16px",
    overflow: "hidden",
    boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.1)"
  },
  preview: {
    width: "100%",
    height: "auto",
    display: "block",
    borderRadius: "16px"
  },
  button: {
    marginTop: "12px",
    padding: "16px",
    borderRadius: "12px",
    backgroundColor: COLORS.primary,
    color: "white",
    fontSize: "16px",
    fontWeight: "600",
    border: "none",
    transition: "all 0.3s ease"
  },
  message: {
    padding: "14px 18px",
    borderRadius: "12px",
    marginBottom: "24px",
    fontSize: "15px",
    fontWeight: "500",
    borderLeft: `5px solid ${COLORS.primary}`
  }
};

export default Enrollment;
